@@ -0,0 +1,88 @@
+import styled from 'styled-components';
+import { transparentize } from 'polished';
+
+const getListHeight = ({ $visibleRows, $rowHeight, $rowGap, $listPadding }) => {
+  const rowsHeight = $rowHeight * $visibleRows;
+  const gapsHeight = $rowGap * Math.max($visibleRows - 1, 0);
+  const paddingHeight = $listPadding * 2;
+  const bordersHeight = 2;
+
+  return `${rowsHeight + gapsHeight + paddingHeight + bordersHeight}px`;
+};
+
+const StyledWrapper = styled.div`
+  .selection-toolbar {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    gap: 0.75rem;
+    margin-bottom: 0.5rem;
+  }
+
+  .selection-title {
+    margin: 0;
+    font-size: ${(props) => props.theme.font.size.base};
+    font-weight: 600;
+  }
+
+  .selection-toggle {
+    display: inline-flex;
+    align-items: center;
+    cursor: pointer;
+    user-select: none;
+    color: ${(props) => props.theme.text};
+    font-size: ${(props) => props.theme.font.size.md};
+    font-weight: 400;
+  }
+
+  .selection-toggle input[type='checkbox'] {
+    cursor: pointer;
+    margin-right: 0.5rem;
+  }
+
+  .selection-list {
+    max-height: ${getListHeight};
+    overflow-y: auto;
+    border: 1px solid ${(props) => transparentize(0.4, props.theme.border.border2)};
+    border-radius: ${(props) => props.theme.border.radius.base};
+    padding: ${(props) => `${props.$listPadding}px 0`};
+    margin: 0;
+    list-style: none;
+  }
+
+  .selection-item {
+    box-sizing: border-box;
+    display: flex;
+    align-items: center;
+    min-height: ${(props) => `${props.$rowHeight}px`};
+    padding: 0.375rem 1rem;
+    cursor: pointer;
+    user-select: none;
+    font-size: ${(props) => props.theme.font.size.md};
+    font-weight: 400;
+  }
+
+  .selection-list li + li .selection-item {
+    margin-top: ${(props) => `${props.$rowGap}px`};
+  }
+
+  .selection-item input[type='checkbox'] {
+    accent-color: ${(props) => props.theme.workspace.accent};
+    cursor: pointer;
+    margin-right: 0.75rem;
+  }
+
+  .selection-path {
+    line-height: 1.2;
+    word-break: break-word;
+  }
+
+  .selection-empty {
+    padding: 0.5rem;
+    color: ${(props) => props.theme.colors.text.muted};
+    font-size: ${(props) => props.theme.font.size.sm};
+    font-style: italic;
+  }
+`;
+
+export default StyledWrapper;
diff --git a/packages/bruno-app/src/components/SelectionList/index.js b/packages/bruno-app/src/components/SelectionList/index.js
new file mode 100644
index 000000000..2913e4803
--- /dev/null
+++ b/packages/bruno-app/src/components/SelectionList/index.js
@@ -0,0 +1,74 @@
+import React, { useRef, useEffect } from 'react';
+import StyledWrapper from './StyledWrapper';
+
+const SelectionList = ({
+  title,
+  items,
+  selectedItems,
+  onSelectAll,
+  onItemToggle,
+  getItemId,
+  renderItemLabel,
+  visibleRows = 8,
+  rowHeight = 30,
+  rowGap = 2,
+  listPadding = 8,
+  emptyMessage = 'No items found'
+}) => {
+  const allSelected = items.length > 0 && selectedItems.length === items.length;
+  const someSelected = items.length > 0 && selectedItems.length > 0 && !allSelected;
+  const selectAllRef = useRef(null);
+
+  useEffect(() => {
+    if (selectAllRef.current) {
+      selectAllRef.current.indeterminate = someSelected;
+    }
+  }, [someSelected]);
+
+  return (
+    <StyledWrapper
+      $visibleRows={visibleRows}
+      $rowHeight={rowHeight}
+      $rowGap={rowGap}
+      $listPadding={listPadding}
+    >
+      <div className="selection-toolbar">
+        <span className="selection-title">{title}</span>
+        <label className="selection-toggle">
+          <input
+            ref={selectAllRef}
+            className="checkbox"
+            type="checkbox"
+            checked={allSelected}
+            onChange={onSelectAll}
+          />
+          Select All
+        </label>
+      </div>
+      <ul className="selection-list scrollbar-hover">
+        {items.length === 0 && (
+          <li className="selection-empty">{emptyMessage}</li>
+        )}
+        {items.map((item) => {
+          const itemId = getItemId(item);
+          const isSelected = selectedItems.includes(itemId);
+
+          return (
+            <li key={itemId}>
+              <label className="selection-item">
+                <input
+                  type="checkbox"
+                  checked={isSelected}
+                  onChange={() => onItemToggle(itemId)}
+                />
+                <span className="selection-path">{renderItemLabel(item)}</span>
+              </label>
+            </li>
+          );
+        })}
+      </ul>
+    </StyledWrapper>
+  );
+};
+
+export default SelectionList;
