+    if (!isUnchecking && field && field.args && field.args.length > 0) {
+      setEnabledArgs((prev) => {
+        const next = new Set(prev);
+        for (const arg of field.args) {
+          const key = `${path}.${arg.name}`;
+          if (arg.isRequired) {
+            next.add(key);
+          }
+        }
