index 000000000..62a3b759e
--- /dev/null
+++ b/packages/bruno-app/src/utils/graphql/queryBuilder.js
@@ -0,0 +1,715 @@
+import {
+  isScalarType,
+  isEnumType,
+  isObjectType,
+  isInterfaceType,
+  isUnionType,
+  isInputObjectType,
+  isNonNullType,
+  isListType,
+  getNamedType,
+  parse as gqlParse,
+  print,
+  Kind
